# Clean tile-shift search: each band is 3x6 tile shifted by (dr,dc) placed into 3x6 output box; dropped cells vanish; no conflicts.
def solve(inp,o):
    bands=[inp[i*3:(i+1)*3] for i in range(4)]
    sols=[]
    for drs in itertools.product(range(-2,3),repeat=4):
        for dcs in itertools.product(range(-5,6),repeat=4):
            g=[[None]*6 for _ in range(3)]; ok=True
            for bi,(bb,dr,dc) in enumerate(zip(bands,drs,dcs)):
                for rr in range(3):
                    for cc in range(6):
                        v=bb[rr][cc]
                        if v==0: continue
                        # place at (rr+dr, cc+dc); out of box = transparent
                        tr,tc=rr+dr,cc+dc
                        if not (0<=tr<3 and 0<=tc<6): continue
                        if g[tr][tc] is None: g[tr][tc]=v
                        elif g[tr][tc]!=v: ok=False
                if not ok: break
            if ok and g==o: sols.append((drs,dcs))
    return sols
for p in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 4','Demo pair 5']:
    inp=G[p+' input']; o=G[p+' output']
    sols=solve(inp,o)
    print(p,'exact sols:',len(sols),'sample',sols[:2])

